	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/api/v1/auth/mfa/verify", wrapper.VerifyMfaLogin)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/api/v1/auth/session/renew", wrapper.RenewSession)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/api/v1/backups", wrapper.ListBackups)
